class IGOFrontEnd { public: virtual ~IGOFrontEnd(); };
class PauseMenuSystem { public: virtual ~PauseMenuSystem(); };
class GraphicalMenuSystem { public: virtual ~GraphicalMenuSystem(); };
class PanelAnimFile { public: virtual ~PanelAnimFile(); };
class FloatingPQ { public: virtual ~FloatingPQ(); };
class BeachFrontEnd { public: virtual ~BeachFrontEnd(); };
class HelpbarFE { public: virtual ~HelpbarFE(); };

class Font
{
  char data_[9512];

public:
  ~Font();
  void unload();
};

class FEManager
{
public:
  IGOFrontEnd *IGO;
  PauseMenuSystem *pms;
  GraphicalMenuSystem *gms;
  char before_fonts[11456];
  Font trick_font;
  Font numberFont;
  Font font_hand;
  Font font_thin;
  Font font_bold;
  Font font_info;
  Font font_bold_old;
  Font font_body;
  char before_paf[72];
  PanelAnimFile *paf;
  char before_map[68];
  BeachFrontEnd *map;
  HelpbarFE *helpbar;
  char before_default_pq[8];
  FloatingPQ *default_pq;

  virtual ~FEManager();
};

FEManager::~FEManager()
{
  delete IGO;
  delete pms;
  delete gms;
  delete paf;
  delete default_pq;
  delete map;
  delete helpbar;
  trick_font.unload();
  numberFont.unload();
  //clockFont.unload();

  font_hand.unload();
  font_thin.unload();
  font_bold.unload();
  font_info.unload();
  font_bold_old.unload();
  font_body.unload();
}
